import{_ as t,H as a,f as r,i as s}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"第2季回归丨大数据之后，让我们回归后端","description":"","frontmatter":{},"headers":[],"relativePath":"从0开始学大数据/第2季回归丨大数据之后，让我们回归后端.md","filePath":"从0开始学大数据/第2季回归丨大数据之后，让我们回归后端.md","lastUpdated":1779818299000}'),i={name:"从0开始学大数据/第2季回归丨大数据之后，让我们回归后端.md"};function n(o,e,_,p,m,E){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="第2季回归丨大数据之后-让我们回归后端" tabindex="-1">第2季回归丨大数据之后，让我们回归后端 <a class="header-anchor" href="#第2季回归丨大数据之后-让我们回归后端" aria-label="Permalink to &quot;第2季回归丨大数据之后，让我们回归后端&quot;">​</a></h1><p>你好，我是李智慧。</p><p>距离“从0开始学大数据”专栏的结束已经过去9个月了。在这9个月中，我一直都在准备另一个专栏的内容。11月18号，这个专栏终于上线，那就是“ <a href="https://time.geekbang.org/column/intro/254?utm_term=zeusE44XI&amp;utm_source=geektime&amp;utm_medium=dashuju" target="_blank" rel="noreferrer">后端技术基础详解</a>”。</p><p>之所以要出这个专栏，是因为我在这么多年的面试过程中，发现很多后端人常常面临的窘境就是，面对纷繁复杂的技术，不知道从何学起，也不知道要学到何种程度。</p><p>所以，在这个专栏中，我将带你系统梳理后端技术框架，从最简单、最常见的问题场景出发，一步步剖析其背后的原理。建立后端技术框架，理解技术中的第一性原理，会让我们面对变化万千的技术潮流时，更加从容。</p><p>专栏共4个模块，37篇文章。按照顺序依次讲解软件的基础原理、软件的设计原理、架构的核心原理以及技术人的思维修炼。</p><p>下面是专栏目录：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%AD%A6%E5%A4%A7%E6%95%B0%E6%8D%AE/images/168090/0e4c7f1b5acafa8bf8ed829fda702f90.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%AD%A6%E5%A4%A7%E6%95%B0%E6%8D%AE/images/168090/0e4c7f1b5acafa8bf8ed829fda702f90.jpg" alt=""></a></p><p>期待与你的相遇！</p><p><a href="https://time.geekbang.org/column/intro/254?utm_term=zeusE44XI&amp;utm_source=geektime&amp;utm_medium=dashuju" target="_blank" rel="noreferrer"><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%AD%A6%E5%A4%A7%E6%95%B0%E6%8D%AE/images/168090/d2194c139130946737870ef207a75ab6.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%AD%A6%E5%A4%A7%E6%95%B0%E6%8D%AE/images/168090/d2194c139130946737870ef207a75ab6.jpg" alt=""></a></a></p>',10)])])}const g=t(i,[["render",n]]);export{c as __pageData,g as default};
